import java.math.BigInteger;

public BigInteger fibonacciModified(int t1, int t2, int n) {
    return t(n, BigInteger.valueOf(t1), BigInteger.valueOf(t2));
}

private BigInteger t(int i, BigInteger a, BigInteger b) {
    if (i == 1) return a;
    if (i == 2) return b;
    BigInteger prev2 = t(i - 2, a, b);
    BigInteger prev1 = t(i - 1, a, b);
    return prev2.add(prev1.multiply(prev1));
}

