import java.math.BigInteger;

public BigInteger fibonacciModified(int t1, int t2, int n) {
    if (n == 1) return BigInteger.valueOf(t1);
    if (n == 2) return BigInteger.valueOf(t2);
    BigInteger prev = BigInteger.valueOf(t1);
    BigInteger cur = BigInteger.valueOf(t2);
    for (int i = 3; i <= n; i++) {
        BigInteger next = prev.add(cur.multiply(cur));
        prev = cur;
        cur = next;
    }
    return cur;
}

