def fibonacci_modified(self, t1: int, t2: int, n: int) -> int:
    if n == 1:
        return t1
    if n == 2:
        return t2
    prev, cur = t1, t2
    for _ in range(3, n + 1):
        prev, cur = cur, prev + cur * cur
    return cur

